package app.dayflow;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import org.json.*;
/** No resident listener. Caller must explicitly possess the opt-in device-local token. */
public final class ApiProvider extends ContentProvider {public boolean onCreate(){return true;}public Bundle call(String method,String arg,Bundle extras){Bundle result=new Bundle();try{Context c=getContext();if(method.equals("commit_document")){if(c.checkCallingPermission("app.dayflow.permission.INTERNAL")!=android.content.pm.PackageManager.PERMISSION_GRANTED)throw new SecurityException("需要同发布者的文档插件");JSONObject saved=DocumentPlugins.commit(c,extras.getString("title"),extras.getString("sha256"),extras.getString("document_token"));result.putInt("status",200);result.putString("json",saved.toString());return result;}if(!AssistantApi.enabled(c))throw new SecurityException("API已关闭");String expected=Secrets.get(c,"assistant_api"),provided=extras==null?"":extras.getString("token","");if(expected.isEmpty()||!java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.UTF_8),provided.getBytes(java.nio.charset.StandardCharsets.UTF_8)))throw new SecurityException("API密钥无效");JSONObject input=new JSONObject(extras.getString("json","{}"));JSONObject value=AssistantApi.execute(c,method,input);AgendaWidget.refresh(c);if(java.util.Arrays.asList("create_task","complete_task","capture").contains(method))ReminderReceiver.refresh(c);result.putString("json",value.toString());result.putInt("status",200);}catch(SecurityException e){result.putInt("status",401);result.putString("error",e.getMessage());}catch(Exception e){result.putInt("status",400);result.putString("error",e.getMessage()==null?"请求失败":e.getMessage());}return result;}public Cursor query(Uri u,String[] projection,String selection,String[] args,String order){throw new UnsupportedOperationException("请使用授权call接口");}public String getType(Uri u){return "application/json";}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}}
